// 프론트엔드(MVP)가 보낸 요청 본문 읽기
const raw = $input.first().json;
let b = raw.body ?? raw;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
const v = (x, d) => (x === undefined || x === null || x === '' ? d : x);

// ▼ 데모용 인플루언서 후보 DB (가상의 인물). 실제 검색 API 연동 전까지 이 목록에서 추천합니다.
//   실제 운영 시 이 부분을 Google Sheets / 인플루언서 검색 API 노드로 교체하면 됩니다.
const DB = [
  { handle: '@glowwith_hana', name: '하나의 피부일기', platform: '인스타그램', tags: ['뷰티','스킨케어'], followers: 48000, engagement_rate: 5.8, avg_cost: 350000, audience: '20~30대 여성 82%', note: '민감성 피부 루틴 콘텐츠' },
  { handle: '@daily_minji', name: '민지의 데일리', platform: '인스타그램', tags: ['뷰티','패션','라이프'], followers: 125000, engagement_rate: 3.1, avg_cost: 900000, audience: '20대 여성 75%', note: '데일리룩·메이크업' },
  { handle: '@skin_lab_doc', name: '피부연구소 J', platform: '유튜브', tags: ['뷰티','스킨케어'], followers: 210000, engagement_rate: 4.2, avg_cost: 2500000, audience: '25~39세 여성 68%', note: '성분 분석 리뷰' },
  { handle: '@ondo_vlog', name: '온도 브이로그', platform: '유튜브', tags: ['라이프','리빙'], followers: 86000, engagement_rate: 6.5, avg_cost: 800000, audience: '20~30대 1인 가구', note: '자취·살림 브이로그' },
  { handle: '@fitjun', name: '핏준', platform: '인스타그램', tags: ['푸드','건강','운동'], followers: 67000, engagement_rate: 4.9, avg_cost: 450000, audience: '20~30대 남성 60%', note: '홈트·식단' },
  { handle: '@salad_mom', name: '샐러드맘', platform: '인스타그램', tags: ['푸드','건강','육아'], followers: 39000, engagement_rate: 7.2, avg_cost: 250000, audience: '30~40대 여성 80%', note: '건강 간식 레시피' },
  { handle: '@tech_ssam', name: '테크쌤', platform: '유튜브', tags: ['테크','리빙'], followers: 320000, engagement_rate: 3.4, avg_cost: 3500000, audience: '20~40대 남성 70%', note: '가전·IT 리뷰' },
  { handle: '@mood_room', name: '무드룸', platform: '인스타그램', tags: ['리빙','인테리어'], followers: 54000, engagement_rate: 5.1, avg_cost: 400000, audience: '25~35세 여성 77%', note: '원룸 인테리어' },
  { handle: '@ootd_seoul', name: '서울 오오티디', platform: '틱톡', tags: ['패션','뷰티'], followers: 180000, engagement_rate: 8.3, avg_cost: 700000, audience: '10~20대 64%', note: '숏폼 스타일링' },
  { handle: '@cleanbeauty_yu', name: '유의 클린뷰티', platform: '틱톡', tags: ['뷰티','스킨케어'], followers: 92000, engagement_rate: 9.1, avg_cost: 500000, audience: '18~29세 여성 79%', note: '숏폼 성분·사용감 리뷰' },
  { handle: '@hometable_k', name: '홈테이블', platform: '유튜브', tags: ['푸드','리빙'], followers: 145000, engagement_rate: 4.6, avg_cost: 1500000, audience: '30~50대 여성 71%', note: '집밥·주방용품' },
  { handle: '@gadget_bori', name: '가젯보리', platform: '틱톡', tags: ['테크','라이프'], followers: 76000, engagement_rate: 7.7, avg_cost: 400000, audience: '20대 58%', note: '신기한 아이템 숏폼' },
];

const p = {
  product: v(b.product, '이름 미입력 제품'),
  category: v(b.category, '뷰티'),
  price: Number(v(b.price, 0)),
  features: v(b.features, ''),
  target: v(b.target, ''),
  budget: Number(v(b.budget, 1000000)),
  goal: v(b.goal, '인지도 확대'),
  platform: v(b.platform, '상관없음'),
  past_collabs: Array.isArray(b.past_collabs) ? b.past_collabs : [],
};

// ▼ 적합도 점수 (규칙 기반, 100점 만점) — AI가 숫자를 지어내지 않도록 코드로 계산
const scored = DB.map(i => {
  let s = 0; const why = [];
  if (i.tags.includes(p.category)) { s += 40; why.push('카테고리 일치 +40'); }
  s += Math.round(Math.min(i.engagement_rate / 8, 1) * 25); why.push(`참여율 ${i.engagement_rate}%`);
  if (i.avg_cost <= p.budget * 0.4) { s += 20; why.push('예산 여유 +20'); }
  else if (i.avg_cost <= p.budget) { s += 10; why.push('예산 내 +10'); }
  else why.push('예산 초과');
  if (p.platform === '상관없음' || i.platform === p.platform) { s += 15; }
  const past = p.past_collabs.find(c => c.handle === i.handle);
  if (past && past.result === 'good') { s += 10; why.push('과거 협업 성과 좋음 +10'); }
  if (past && past.result === 'bad') { s -= 15; why.push('과거 협업 아쉬움 -15'); }
  return { ...i, fit_score: Math.max(0, Math.min(100, s)), score_detail: why.join(', ') };
}).sort((a, b2) => b2.fit_score - a.fit_score);

const top = scored.slice(0, 5);

let prompt = `아래 제품에 맞는 인플루언서 협업 계획을 작성해줘.

[제품 정보]
- 제품명: ${p.product} / 카테고리: ${p.category} / 판매가: ${p.price.toLocaleString()}원
- 특징: ${p.features}
- 타겟: ${p.target}
- 인플루언서 협업 예산: ${p.budget.toLocaleString()}원
- 협업 목표: ${p.goal} / 희망 플랫폼: ${p.platform}

[후보 인플루언서 목록 — 적합도 점수 높은 순, 이 안에서만 추천]
${top.map((i, n) => `${n + 1}. ${i.handle} (${i.name}) | ${i.platform} | 팔로워 ${i.followers.toLocaleString()} | 참여율 ${i.engagement_rate}% | 평균 단가 ${i.avg_cost.toLocaleString()}원 | 주 시청층 ${i.audience} | ${i.note} | 적합도 ${i.fit_score}점 (${i.score_detail})`).join('\n')}

[과거 협업 이력]
${p.past_collabs.length ? p.past_collabs.map(c => `${c.handle}: ${c.result === 'good' ? '성과 좋음' : '성과 아쉬움'} ${c.memo || ''}`).join('\n') : '없음'}

[출력 형식] 아래 JSON 구조 그대로, 값만 채워서 출력:
{
  "summary": "추천 전략 한 줄 요약",
  "recommendations": [ { "handle": "@목록의 핸들 그대로", "reason": "추천 이유", "risk": "주의할 점", "suggested_offer": "제안 조건(예: 제품 제공 + 원고료 30만원)" } ],
  "proposal_dm": { "to": "@1순위 핸들", "message": "첫 협업 제안 DM 전문" },
  "contract_draft": { "title": "계약서 제목", "clauses": [ { "title": "제1조 (조항명)", "content": "조항 내용" } ], "note": "유의사항" },
  "content_brief": { "key_messages": ["핵심 메시지"], "dos": ["꼭 해주세요"], "donts": ["피해주세요"], "schedule": "초안 제출·수정·게시 일정" }
}

recommendations는 3명(예산 안에서 실행 가능한 조합 우선), contract_draft.clauses는 8개 이상.`;

// 대표의 수정 요청이 있으면 이전 결과와 함께 전달 (승인 → 수정 → 재승인 왕복 흐름)
if (b.feedback) {
  prompt += `\n\n[대표 수정 요청]\n${b.feedback}\n\n[이전 결과]\n${JSON.stringify(b.previous || {}).slice(0, 8000)}\n\n위 수정 요청을 반드시 반영해서, 같은 JSON 형식으로 전체 결과를 다시 작성해줘. 수정 요청과 관계없는 좋은 부분은 유지해.`;
}

return [{ json: { prompt, request: p, candidates: top, startedAt: Date.now() } }];

// AI 응답에서 JSON만 안전하게 꺼내기
function parseJson(t) {
  t = String(t || '').replace(/```json/gi, '').replace(/```/g, '');
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  if (s < 0 || e < 0) throw new Error('JSON not found');
  return JSON.parse(t.slice(s, e + 1));
}

const out = $input.first().json.output;
const prep = $('요청 정리').first().json;
let data, checks = [];
try { data = parseJson(out); } catch (e) { data = { raw: String(out || '') }; checks.push({ ok: false, label: 'AI 응답 JSON 변환 실패 → 원문 표시' }); }

// 검증: AI가 추천한 후보를 DB와 대조해서 팔로워·참여율·단가는 DB 값으로 덮어쓰기 (수치 오류 0건 목표)
const byHandle = Object.fromEntries(prep.candidates.map(c => [c.handle, c]));
let recs = Array.isArray(data.recommendations) ? data.recommendations : [];
const invented = recs.filter(r => !byHandle[r.handle]).map(r => r.handle);
recs = recs.filter(r => byHandle[r.handle]).map(r => ({ ...byHandle[r.handle], ...r,
  followers: byHandle[r.handle].followers, engagement_rate: byHandle[r.handle].engagement_rate,
  avg_cost: byHandle[r.handle].avg_cost, fit_score: byHandle[r.handle].fit_score }));
if (invented.length) checks.push({ ok: false, label: `목록에 없는 후보 제거: ${invented.join(', ')}` });
else checks.push({ ok: true, label: '추천 후보 전원 DB 확인 완료, 수치는 DB 원본 사용' });
if (!recs.length) recs = prep.candidates.slice(0, 3).map(c => ({ ...c, reason: '적합도 점수 기준 자동 추천', risk: '-', suggested_offer: '-' }));
data.recommendations = recs;

const total = recs.reduce((a, c) => a + c.avg_cost, 0);
checks.push(total <= prep.request.budget
  ? { ok: true, label: `추천 3인 평균 단가 합계 ${total.toLocaleString()}원 ≤ 예산` }
  : { ok: false, label: `추천 3인 단가 합계 ${total.toLocaleString()}원이 예산 초과 → 조합 조정 필요` });

return [{ json: { ok: true, type: 'influencer', generated_at: new Date().toISOString(), elapsed_ms: Date.now() - prep.startedAt, checks, candidates: prep.candidates, data } }];
